<?php $definition=$a->threads->definition((int)($editing['id']??0));$threadModes=['discussion'=>tr('Discussion')];if($s->enabled('questions')){$threadModes['question']=tr('Question');}if($s->enabled('polls')){$threadModes['poll']=tr('Poll');}if(!isset($threadModes[$definition['mode']])){$threadModes[$definition['mode']]=tr($definition['mode']);} ?>
<div class="thread-editor"><span class="eyebrow">COMMUNITY FORMAT</span><?php select_field('thread_mode','Conversation type',$threadModes,$definition['mode'],['data-thread-mode'=>'']); ?>
<div data-poll-fields><?php field('poll_question','Poll question',$definition['poll_question'],'text',['maxlength'=>'255']);field('poll_options','Poll options (one per line)',implode("\n",array_column($a->threads->options((int)($editing['id']??0)),'label')),'textarea',['maxlength'=>'2200']);field('poll_closes_at','Poll closing time (optional)',(int)$definition['closes_at']?date('Y-m-d\TH:i',(int)$definition['closes_at']):'','datetime-local');field('poll_max_choices','Maximum choices per ballot',$definition['max_choices']??1,'number',['min'=>'1','max'=>'10']);select_field('poll_results','Show poll results',options(['always','after_vote','closed']),$definition['results_rule']); ?>
<p class="hint"><?= t('One ballot per account. Choice count and result privacy lock after the first vote.') ?></p></div></div><div class="field-divider"></div>
